// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public { 
        deployer = address(this);
        c = new C(address(this), address(this)); 
    }

    function testFuzz_property(address _rewardToken) public {
        vm.assume(_rewardToken != address(0));

        // Only owner can call addReward
        vm.prank(deployer);
        c.addReward(_rewardToken);

        // The owner must be the deployer
        assertTrue(c.owner() == deployer);
    }
}

